import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { eq } from "drizzle-orm";

vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { getDb, subscriptions } from "@/server/db";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityService from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { OrgId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function projectInput(orgId: OrgId, n: number) {
  return {
    orgId,
    name: `Project ${n}`,
    slug: `project-${n}`,
    key: `PR${n}`,
    description: null,
    visibility: "org" as const,
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

function expireTrial(orgId: OrgId): void {
  getDb()
    .update(subscriptions)
    .set({ currentPeriodEnd: "2000-01-01T00:00:00.000Z" })
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

describe("scratch: plan follows the subscription", () => {
  it("upgrade free -> growth unlocks projects, the audit export and webhooks", async () => {
    const t = await createTenant("up-free", "free");
    await expect(
      projectService.createProject(t.actors.owner, projectInput(t.org.id, 1)),
    ).resolves.toBeDefined();
    await expect(
      projectService.createProject(t.actors.owner, projectInput(t.org.id, 2)),
    ).rejects.toThrow(/allows 2 projects/);
    await expect(
      activityService.exportActivity(t.actors.admin, {
        orgId: t.org.id,
        since: t.org.createdAt,
        until: t.org.createdAt,
        format: "csv",
      }),
    ).rejects.toThrow(/not included/);

    await billingService.changePlan(t.actors.owner, {
      orgId: t.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect((await orgRepo.findOrgById(t.org.id))?.plan).toBe("growth");
    await expect(
      projectService.createProject(t.actors.owner, projectInput(t.org.id, 2)),
    ).resolves.toBeDefined();
    await expect(
      activityService.exportActivity(t.actors.admin, {
        orgId: t.org.id,
        since: t.org.createdAt,
        until: t.org.createdAt,
        format: "csv",
      }),
    ).resolves.toEqual(expect.any(String));
    await expect(
      webhookService.createWebhook(t.actors.admin, {
        orgId: t.org.id,
        url: "https://example.com/hook",
        eventTypes: ["issue.created"],
      }),
    ).resolves.toBeDefined();
  });

  it("downgrade growth -> starter refuses new webhook endpoints", async () => {
    const t = await createTenant("down-growth", "growth");
    await billingService.changePlan(t.actors.owner, {
      orgId: t.org.id,
      plan: "starter",
      interval: "monthly",
    });
    expect((await orgRepo.findOrgById(t.org.id))?.plan).toBe("starter");
    await expect(
      webhookService.createWebhook(t.actors.admin, {
        orgId: t.org.id,
        url: "https://example.com/hook",
        eventTypes: ["issue.created"],
      }),
    ).rejects.toThrow(/not included/);
  });

  it("a stale org row does not win over the subscription", async () => {
    const t = await createTenant("disagree", "free");
    getDb()
      .update(subscriptions)
      .set({ plan: "growth" })
      .where(eq(subscriptions.orgId, t.org.id))
      .run();

    expect((await orgRepo.findOrgById(t.org.id))?.plan).toBe("growth");
    await expect(
      projectService.createProject(t.actors.owner, projectInput(t.org.id, 2)),
    ).resolves.toBeDefined();
    await expect(
      projectService.createProject(t.actors.owner, projectInput(t.org.id, 3)),
    ).resolves.toBeDefined();
  });

  it("a workspace without a subscription keeps its own plan", async () => {
    const owner = await createTenant("nosub-owner", "free");
    const org = await orgRepo.insertOrg({ name: "No Sub", slug: "no-sub", plan: "growth" }, owner.org.ownerId);
    expect((await orgRepo.findOrgById(org.id))?.plan).toBe("growth");
  });

  it("burst limits follow the plan, per workspace", async () => {
    const free = await createTenant("burst-free", "free");
    const growth = await createTenant("burst-growth", "growth");

    let freeAllowed = 0;
    for (let i = 0; i < 100; i += 1) {
      if ((await billingService.chargeBurstLimit(free.org.id, "comment:create")).allowed) {
        freeAllowed += 1;
      }
    }
    let growthAllowed = 0;
    for (let i = 0; i < 100; i += 1) {
      if ((await billingService.chargeBurstLimit(growth.org.id, "comment:create")).allowed) {
        growthAllowed += 1;
      }
    }
    expect(freeAllowed).toBe(60);
    expect(growthAllowed).toBe(100);
  });

  it("a refused downgrade changes nothing", async () => {
    const t = await createTenant("refused", "growth");
    await usageRepo.incrementUsage(t.org.id, { seatsUsed: 5 });
    await expect(
      billingService.changePlan(t.actors.owner, { orgId: t.org.id, plan: "free", interval: "monthly" }),
    ).rejects.toThrow(/seats exceeds/);
    expect((await orgRepo.findOrgById(t.org.id))?.plan).toBe("growth");
    expect((await subscriptionRepo.findSubscription(t.org.id))?.plan).toBe("growth");
  });

  it("an expired trial moves to free, the org follows, and a second sweep changes nothing", async () => {
    const t = await createTenant("trial-expire", "growth");
    expireTrial(t.org.id);

    const first = await runTrialExpiryJob(new Date());
    expect(first.processed).toBeGreaterThanOrEqual(1);
    expect((await subscriptionRepo.findSubscription(t.org.id))?.plan).toBe("free");
    expect((await orgRepo.findOrgById(t.org.id))?.plan).toBe("free");
    await expect(
      projectService.createProject(t.actors.owner, projectInput(t.org.id, 2)),
    ).resolves.toBeDefined();
    await expect(
      projectService.createProject(t.actors.owner, projectInput(t.org.id, 3)),
    ).rejects.toThrow(/allows 2 projects/);

    const before = await subscriptionRepo.findSubscription(t.org.id);
    const second = await runTrialExpiryJob(new Date());
    const after = await subscriptionRepo.findSubscription(t.org.id);
    expect(after).toEqual(before);
    expect(second.processed).toBe(0);
  });

  it("a trial that outgrew free stays on its plan", async () => {
    const t = await createTenant("trial-outgrown", "growth");
    await usageRepo.incrementUsage(t.org.id, { projectsUsed: 5 });
    expireTrial(t.org.id);

    await runTrialExpiryJob(new Date());
    expect((await subscriptionRepo.findSubscription(t.org.id))?.plan).toBe("growth");
    expect((await orgRepo.findOrgById(t.org.id))?.plan).toBe("growth");
  });

  it("a paid plan chosen during the trial is not swept when the trial window ends", async () => {
    const t = await createTenant("paid-in-trial", "growth");
    await billingService.changePlan(t.actors.owner, {
      orgId: t.org.id,
      plan: "enterprise",
      interval: "monthly",
    });
    expireTrial(t.org.id);

    await runTrialExpiryJob(new Date());
    expect((await subscriptionRepo.findSubscription(t.org.id))?.plan).toBe("enterprise");
    expect((await orgRepo.findOrgById(t.org.id))?.plan).toBe("enterprise");
  });
});

